// i18n-extra.js (see index.html); scripts/build-pages.mjs reads it too.

(function () {
    const lessons = [
        {
            id: 16,
            title: 'AI Agents: Model yang Bertindak',
            desc: 'Memahami cara LLM merencanakan langkah, memanggil tool, dan menyelesaikan tugas dengan batas keamanan yang jelas.',
            level: 'Menengah',
            duration: '25 menit',
            sections: [
                {
                    title: 'Dari Chatbot ke Agen',
                    content: 'Chatbot menjawab satu pesan lalu berhenti. Agen menjalankan LLM di dalam loop: membaca tujuan, memilih langkah, memanggil tool, membaca hasilnya, lalu memutuskan langkah berikutnya sampai tugas selesai. Pola ReAct menggabungkan penalaran dan aksi secara bergantian. Contoh: agen layanan pelanggan mengecek status pesanan, membaca kebijakan retur, lalu menyiapkan refund. Gunakan agen hanya bila langkahnya tidak bisa ditentukan sejak awal; alur yang tetap lebih murah dan lebih mudah diuji sebagai workflow biasa.'
                },
                {
                    title: 'Tool Calling dan Function Schema',
                    content: 'Setiap tool dideskripsikan dengan nama, penjelasan, dan JSON Schema untuk argumennya, misalnya get_order(order_id: string). Model tidak menjalankan kode sendiri; ia mengembalikan panggilan terstruktur, aplikasi memvalidasi argumen dan mengeksekusinya, lalu hasilnya dikirim kembali ke model. Model Context Protocol (MCP) menstandarkan cara aplikasi menyediakan tool dan data untuk model. Deskripsi tool yang jelas, argumen yang divalidasi, dan pesan error yang informatif sering lebih menentukan keberhasilan agen daripada pilihan modelnya.'
                },
                {
                    title: 'Memori, Perencanaan, dan Multi-Agen',
                    content: 'Memori jangka pendek adalah riwayat percakapan di context window; memori jangka panjang biasanya disimpan di database atau vector store lalu diambil saat relevan. Untuk tugas panjang, agen dapat memecah tujuan menjadi rencana bertahap dan memperbaruinya setelah setiap hasil. Pola orchestrator-worker membagi subtugas ke beberapa agen yang bekerja paralel, misalnya riset beberapa sumber sekaligus. Setiap agen tambahan menambah biaya token, latensi, dan titik gagal, jadi mulai dari satu agen yang sederhana.'
                },
                {
                    title: 'Keamanan dan Evaluasi Agen',
                    content: 'Teks dari halaman web, email, atau dokumen bisa berisi prompt injection yang menyuruh agen melakukan hal lain. Beri tool hak akses seminimal mungkin, jalankan kode di sandbox, batasi jumlah langkah dan anggaran, dan minta persetujuan manusia sebelum tindakan yang sulit dibatalkan seperti transfer dana atau menghapus data. Simpan trace setiap langkah untuk audit. Evaluasi agen dengan kumpulan tugas nyata dan ukur tingkat keberhasilan, jumlah langkah, biaya, serta kesalahan fatal; benchmark seperti SWE-bench dan τ-bench memakai pendekatan yang sama.'
                }
            ]
        },
        {
            id: 17,
            title: 'RAG dan Evaluasi Aplikasi LLM',
            desc: 'Membangun jawaban LLM yang berpijak pada dokumen Anda, lalu mengukur kualitas retrieval dan jawabannya secara sistematis.',
            level: 'Menengah',
            duration: '25 menit',
            sections: [
                {
                    title: 'Mengapa RAG',
                    content: 'LLM hanya tahu isi data latihnya, punya batas tanggal pengetahuan, dan bisa berhalusinasi dengan percaya diri. Retrieval-Augmented Generation (RAG) mencari potongan dokumen yang relevan saat pertanyaan masuk, lalu menyisipkannya ke prompt agar model menjawab berdasarkan sumber itu. Hasilnya bisa diperbarui tanpa melatih ulang model, dan setiap jawaban dapat menyertakan sitasi. Fine-tuning lebih cocok untuk mengubah gaya atau format jawaban; RAG lebih cocok untuk pengetahuan yang sering berubah, seperti kebijakan perusahaan.'
                },
                {
                    title: 'Chunking, Embedding, dan Vector Search',
                    content: 'Dokumen dipecah menjadi chunk sekitar 200 sampai 800 token dengan sedikit overlap agar kalimat tidak terpotong maknanya. Setiap chunk diubah oleh model embedding menjadi vektor, lalu disimpan di vector database seperti pgvector, Qdrant, atau FAISS. Pertanyaan juga diubah menjadi vektor, dan sistem mengambil top-k chunk dengan cosine similarity tertinggi. Hybrid search menggabungkan pencarian vektor dengan BM25 untuk istilah persis seperti kode produk, lalu reranker mengurutkan ulang kandidat sebelum dikirim ke model.'
                },
                {
                    title: 'Menyusun Prompt dan Sitasi',
                    content: 'Masukkan chunk terpilih ke prompt beserta ID dan judul sumbernya, lalu instruksikan model untuk menjawab hanya dari konteks itu, menyebut sumber seperti [dok-3], dan berkata "tidak tahu" bila jawabannya tidak ada. Konteks yang terlalu panjang menambah biaya dan bisa membuat informasi di tengah terlewat, jadi kirim chunk yang paling relevan saja. Terapkan filter metadata dan hak akses saat retrieval, bukan setelahnya, agar pengguna tidak pernah menerima isi dokumen yang tidak boleh mereka lihat.'
                },
                {
                    title: 'Mengevaluasi Aplikasi LLM',
                    content: 'Buat golden dataset berisi puluhan sampai ratusan pertanyaan nyata beserta dokumen dan jawaban yang benar. Ukur retrieval dengan recall@k dan MRR: apakah chunk yang tepat ikut terambil? Ukur jawaban dengan faithfulness (semua klaim didukung sumber) dan answer relevance (benar-benar menjawab pertanyaan). LLM-as-a-judge dengan rubrik jelas mempercepat penilaian, tetapi kalibrasi dulu dengan penilaian manusia. Jalankan evaluasi ini di CI setiap kali prompt, model, atau pipeline berubah, dan pantau latensi serta biaya di produksi.'
                }
            ]
        }
    ];

    const quiz = [
        // AI Agents
        { q: 'Pola agen yang bergantian antara langkah penalaran dan pemanggilan tool disebut?', opts: ['ReAct', 'Dropout', 'Backpropagation', 'Tokenization'], ans: 0 },
        { q: 'Mengapa agen sebaiknya meminta persetujuan manusia sebelum melakukan refund atau menghapus data?', opts: ['Agar biaya token lebih murah', 'Karena tindakan itu sulit dibatalkan dan bisa dipicu prompt injection', 'Karena LLM tidak bisa membaca JSON', 'Agar model otomatis dilatih ulang'], ans: 1 },
        // RAG & LLM evaluation
        { q: 'Dalam RAG, apa fungsi model embedding?', opts: ['Mengompresi gambar', 'Mengubah teks menjadi vektor agar potongan yang maknanya mirip bisa ditemukan', 'Mengenkripsi database', 'Menambah jumlah parameter LLM'], ans: 1 },
        { q: 'Metrik yang menilai apakah semua klaim dalam jawaban didukung dokumen sumber disebut?', opts: ['Faithfulness', 'Learning rate', 'Recall@k', 'Perplexity'], ans: 0 }
    ];

    // Per language: [title, desc, section titles, section bodies] for 16 and 17, then the quiz entries
    // (a string when the options are technical terms, [question, options] when they need translating).
    const translations = {
        en: {
            16: ['AI Agents: Models That Act', 'Understand how LLMs plan steps, call tools and finish tasks within clear safety limits.',
                ['From Chatbot to Agent', 'Tool Calling and Function Schemas', 'Memory, Planning and Multi-Agent Systems', 'Agent Safety and Evaluation'],
                ['A chatbot answers one message and stops. An agent runs an LLM in a loop: it reads the goal, picks a step, calls a tool, reads the result and decides the next step until the task is done. The ReAct pattern alternates reasoning and action. Example: a support agent checks an order status, reads the return policy, then prepares a refund. Use an agent only when the steps cannot be fixed in advance; a fixed flow is cheaper and easier to test as an ordinary workflow.',
                    'Each tool is described with a name, an explanation and a JSON Schema for its arguments, for example get_order(order_id: string). The model does not run code itself; it returns a structured call, the application validates the arguments and executes it, and the result goes back to the model. The Model Context Protocol (MCP) standardises how applications expose tools and data to models. Clear tool descriptions, validated arguments and informative error messages often matter more for an agent\'s success than the choice of model.',
                    'Short-term memory is the conversation history in the context window; long-term memory usually lives in a database or vector store and is retrieved when relevant. For long tasks, an agent can break the goal into a step-by-step plan and update it after each result. The orchestrator-worker pattern hands subtasks to several agents working in parallel, for example researching several sources at once. Every extra agent adds token cost, latency and points of failure, so start with one simple agent.',
                    'Text from web pages, emails or documents can contain prompt injection that tells the agent to do something else. Give tools the least privilege possible, run code in a sandbox, cap the number of steps and the budget, and ask a human to approve hard-to-reverse actions such as transferring money or deleting data. Keep a trace of every step for auditing. Evaluate agents on a set of real tasks and measure success rate, number of steps, cost and critical errors; benchmarks such as SWE-bench and τ-bench take the same approach.']],
            17: ['RAG & LLM Application Evaluation', 'Ground LLM answers in your own documents, then measure retrieval and answer quality systematically.',
                ['Why RAG', 'Chunking, Embeddings and Vector Search', 'Building the Prompt and Citations', 'Evaluating LLM Applications'],
                ['An LLM only knows its training data, has a knowledge cutoff and can hallucinate with confidence. Retrieval-Augmented Generation (RAG) searches for relevant document passages when a question arrives and inserts them into the prompt, so the model answers from those sources. Knowledge can be updated without retraining, and every answer can carry citations. Fine-tuning suits changing the style or format of answers; RAG suits knowledge that changes often, such as company policies.',
                    'Documents are split into chunks of roughly 200 to 800 tokens with a little overlap so sentences keep their meaning. An embedding model turns each chunk into a vector, stored in a vector database such as pgvector, Qdrant or FAISS. The question is embedded too, and the system retrieves the top-k chunks with the highest cosine similarity. Hybrid search combines vector search with BM25 for exact terms such as product codes, and a reranker reorders the candidates before they reach the model.',
                    'Put the selected chunks in the prompt with their IDs and source titles, then instruct the model to answer only from that context, cite sources such as [doc-3], and say "I don\'t know" when the answer is not there. Very long context costs more and can make the model miss information in the middle, so send only the most relevant chunks. Apply metadata and access-control filters during retrieval, not afterwards, so users never receive content from documents they are not allowed to see.',
                    'Build a golden dataset of dozens to hundreds of real questions with their source documents and correct answers. Measure retrieval with recall@k and MRR: was the right chunk retrieved at all? Measure answers with faithfulness (every claim is supported by the sources) and answer relevance (it actually answers the question). LLM-as-a-judge with a clear rubric speeds up grading, but calibrate it against human ratings first. Run these evaluations in CI whenever the prompt, model or pipeline changes, and monitor latency and cost in production.']],
            quiz: [
                'Which agent pattern alternates between reasoning steps and tool calls?',
                ['Why should an agent ask a human before issuing a refund or deleting data?', ['To make tokens cheaper', 'Because the action is hard to undo and could be triggered by prompt injection', 'Because LLMs cannot read JSON', 'So the model retrains itself automatically']],
                ['In RAG, what does the embedding model do?', ['Compresses images', 'Turns text into vectors so passages with similar meaning can be found', 'Encrypts the database', 'Adds parameters to the LLM']],
                'Which metric checks whether every claim in an answer is supported by the source documents?'
            ]
        },
        zh: {
            16: ['AI智能体：会行动的模型', '了解LLM如何规划步骤、调用工具，并在明确的安全边界内完成任务。',
                ['从聊天机器人到智能体', '工具调用与函数模式', '记忆、规划与多智能体', '智能体的安全与评估'],
                ['聊天机器人回答一条消息就结束了。智能体则让LLM在循环中运行：读取目标，选择一步，调用工具，读取结果，再决定下一步，直到任务完成。ReAct模式让推理和行动交替进行。例如，客服智能体先查询订单状态，再阅读退货政策，然后准备退款。只有在步骤无法事先确定时才使用智能体；固定的流程做成普通工作流更便宜，也更容易测试。',
                    '每个工具都用名称、说明和参数的JSON Schema来描述，例如get_order(order_id: string)。模型自己不执行代码；它返回一个结构化调用，由应用校验参数并执行，再把结果送回模型。模型上下文协议（MCP）统一了应用向模型提供工具和数据的方式。清晰的工具描述、经过校验的参数和信息充分的错误提示，往往比选择哪个模型更能决定智能体的成败。',
                    '短期记忆是上下文窗口里的对话历史；长期记忆通常保存在数据库或向量库中，需要时再检索出来。面对长任务，智能体可以把目标拆成分步计划，并在每次得到结果后更新计划。编排者-执行者模式把子任务分给多个并行工作的智能体，例如同时调研多个来源。每增加一个智能体，都会增加令牌成本、延迟和故障点，所以先从一个简单的智能体开始。',
                    '网页、邮件或文档中的文字可能包含提示注入，诱使智能体去做别的事。给工具尽可能小的权限，在沙箱中运行代码，限制步数和预算，并在转账、删除数据等难以撤销的操作前请人工批准。保存每一步的轨迹以便审计。用一组真实任务评估智能体，衡量成功率、步数、成本和严重错误；SWE-bench和τ-bench等基准也采用同样的思路。']],
            17: ['RAG与LLM应用评估', '让LLM的回答立足于你自己的文档，并系统地衡量检索质量和回答质量。',
                ['为什么需要RAG', '分块、嵌入与向量检索', '构建提示与引用', '评估LLM应用'],
                ['LLM只知道训练数据里的内容，有知识截止日期，还可能自信地产生幻觉。检索增强生成（RAG）在问题到来时检索相关的文档片段，并插入提示中，让模型依据这些来源作答。知识可以随时更新而无需重新训练，每个回答都能附上引用。微调适合改变回答的风格或格式；RAG适合经常变化的知识，例如公司政策。',
                    '文档被切分成大约200到800个令牌的块，并保留少量重叠，以免句子失去意义。嵌入模型把每个块转换成向量，存入pgvector、Qdrant或FAISS等向量数据库。问题同样被转换成向量，系统取回余弦相似度最高的前k个块。混合检索把向量检索与BM25结合起来，以匹配产品编号等精确词语，再由重排序模型在送入LLM前重新排列候选结果。',
                    '把选中的块连同ID和来源标题放进提示，并指示模型只根据这些上下文作答，用[doc-3]这样的形式注明来源，答案不在其中时就说“不知道”。上下文过长会增加成本，还可能让模型忽略中间的信息，所以只发送最相关的块。在检索阶段就应用元数据和访问权限过滤，而不是事后过滤，确保用户永远拿不到无权查看的文档内容。',
                    '建立一个黄金数据集，包含几十到几百个真实问题及其来源文档和正确答案。用recall@k和MRR衡量检索：正确的块有没有被检索出来？用忠实度（每个论断都有来源支持）和答案相关性（确实回答了问题）衡量回答。带有清晰评分标准的LLM评审可以加快评分，但要先用人工评分校准。每当提示、模型或流程变化时，在CI中运行这些评估，并在生产环境中监控延迟和成本。']],
            quiz: [
                '哪种智能体模式让推理步骤和工具调用交替进行？',
                ['为什么智能体在退款或删除数据之前应先征得人工同意？', ['为了让令牌更便宜', '因为该操作难以撤销，且可能由提示注入触发', '因为LLM无法读取JSON', '为了让模型自动重新训练']],
                ['在RAG中，嵌入模型的作用是什么？', ['压缩图像', '把文本转换成向量，以便找到语义相近的片段', '加密数据库', '增加LLM的参数数量']],
                '哪个指标用来检查回答中的每个论断是否都有来源文档支持？'
            ]
        },
        es: {
            16: ['Agentes de IA: Modelos que Actúan', 'Comprende cómo los LLM planifican pasos, llaman herramientas y completan tareas dentro de límites de seguridad claros.',
                ['Del Chatbot al Agente', 'Llamadas a Herramientas y Esquemas de Funciones', 'Memoria, Planificación y Multiagentes', 'Seguridad y Evaluación de Agentes'],
                ['Un chatbot responde un mensaje y se detiene. Un agente ejecuta un LLM en bucle: lee el objetivo, elige un paso, llama a una herramienta, lee el resultado y decide el siguiente paso hasta terminar la tarea. El patrón ReAct alterna razonamiento y acción. Ejemplo: un agente de soporte consulta el estado de un pedido, lee la política de devoluciones y prepara un reembolso. Usa un agente solo cuando los pasos no se pueden fijar de antemano; un flujo fijo es más barato y fácil de probar como workflow normal.',
                    'Cada herramienta se describe con un nombre, una explicación y un JSON Schema para sus argumentos, por ejemplo get_order(order_id: string). El modelo no ejecuta código por sí mismo: devuelve una llamada estructurada, la aplicación valida los argumentos y la ejecuta, y el resultado vuelve al modelo. El Model Context Protocol (MCP) estandariza cómo las aplicaciones ofrecen herramientas y datos a los modelos. Descripciones claras, argumentos validados y mensajes de error informativos suelen importar más que la elección del modelo.',
                    'La memoria a corto plazo es el historial de la conversación en la ventana de contexto; la memoria a largo plazo suele guardarse en una base de datos o un vector store y se recupera cuando es relevante. En tareas largas, el agente puede dividir el objetivo en un plan por pasos y actualizarlo tras cada resultado. El patrón orquestador-trabajador reparte subtareas entre varios agentes en paralelo, por ejemplo para investigar varias fuentes a la vez. Cada agente extra suma coste de tokens, latencia y puntos de fallo, así que empieza con uno sencillo.',
                    'El texto de páginas web, correos o documentos puede contener inyección de prompts que ordene al agente hacer otra cosa. Da a las herramientas el mínimo privilegio posible, ejecuta código en un sandbox, limita el número de pasos y el presupuesto, y pide aprobación humana antes de acciones difíciles de revertir, como transferir dinero o borrar datos. Guarda una traza de cada paso para auditoría. Evalúa los agentes con tareas reales y mide la tasa de éxito, los pasos, el coste y los errores graves; benchmarks como SWE-bench y τ-bench siguen el mismo enfoque.']],
            17: ['RAG y Evaluación de Aplicaciones LLM', 'Basa las respuestas del LLM en tus propios documentos y mide de forma sistemática la calidad de la recuperación y de las respuestas.',
                ['Por Qué RAG', 'Chunking, Embeddings y Búsqueda Vectorial', 'Construir el Prompt y las Citas', 'Evaluar Aplicaciones LLM'],
                ['Un LLM solo conoce sus datos de entrenamiento, tiene una fecha de corte y puede alucinar con total seguridad. La generación aumentada por recuperación (RAG) busca fragmentos relevantes de documentos cuando llega una pregunta y los inserta en el prompt para que el modelo responda a partir de esas fuentes. El conocimiento se actualiza sin reentrenar y cada respuesta puede incluir citas. El fine-tuning sirve para cambiar el estilo o el formato; RAG sirve para conocimiento que cambia a menudo, como las políticas de una empresa.',
                    'Los documentos se dividen en fragmentos de unos 200 a 800 tokens con un pequeño solapamiento para que las frases conserven su sentido. Un modelo de embeddings convierte cada fragmento en un vector que se guarda en una base vectorial como pgvector, Qdrant o FAISS. La pregunta también se convierte en vector y el sistema recupera los k fragmentos con mayor similitud coseno. La búsqueda híbrida combina vectores con BM25 para términos exactos, como códigos de producto, y un reranker reordena los candidatos antes de enviarlos al modelo.',
                    'Coloca los fragmentos elegidos en el prompt con su ID y el título de la fuente, e indica al modelo que responda solo con ese contexto, cite fuentes como [doc-3] y diga "no lo sé" si la respuesta no está. Un contexto muy largo cuesta más y puede hacer que el modelo pase por alto información del medio, así que envía solo los fragmentos más relevantes. Aplica filtros de metadatos y de permisos durante la recuperación, no después, para que nadie reciba contenido de documentos que no puede ver.',
                    'Crea un golden dataset con decenas o cientos de preguntas reales, sus documentos fuente y las respuestas correctas. Mide la recuperación con recall@k y MRR: ¿se recuperó el fragmento correcto? Mide las respuestas con faithfulness (cada afirmación está respaldada por las fuentes) y answer relevance (de verdad responde a la pregunta). Un LLM como juez con una rúbrica clara acelera la evaluación, pero calíbralo antes con valoraciones humanas. Ejecuta estas evaluaciones en CI cada vez que cambie el prompt, el modelo o el pipeline, y vigila la latencia y el coste en producción.']],
            quiz: [
                '¿Qué patrón de agente alterna pasos de razonamiento y llamadas a herramientas?',
                ['¿Por qué un agente debería pedir aprobación humana antes de hacer un reembolso o borrar datos?', ['Para que los tokens sean más baratos', 'Porque la acción es difícil de revertir y podría desencadenarla una inyección de prompts', 'Porque los LLM no pueden leer JSON', 'Para que el modelo se reentrene solo']],
                ['En RAG, ¿qué hace el modelo de embeddings?', ['Comprime imágenes', 'Convierte texto en vectores para encontrar fragmentos con significado parecido', 'Cifra la base de datos', 'Añade parámetros al LLM']],
                '¿Qué métrica comprueba si cada afirmación de una respuesta está respaldada por los documentos fuente?'
            ]
        },
        ar: {
            16: ['وكلاء الذكاء الاصطناعي: نماذج تتصرف', 'افهم كيف تخطط النماذج اللغوية الكبيرة للخطوات وتستدعي الأدوات وتنجز المهام ضمن حدود أمان واضحة.',
                ['من روبوت المحادثة إلى الوكيل', 'استدعاء الأدوات ومخططات الدوال', 'الذاكرة والتخطيط وتعدد الوكلاء', 'أمان الوكلاء وتقييمهم'],
                ['يجيب روبوت المحادثة عن رسالة واحدة ثم يتوقف. أما الوكيل فيشغّل نموذجًا لغويًا كبيرًا داخل حلقة: يقرأ الهدف، ويختار خطوة، ويستدعي أداة، ويقرأ النتيجة، ثم يقرر الخطوة التالية حتى تنتهي المهمة. يناوب نمط ReAct بين الاستدلال والفعل. مثال: وكيل دعم يتحقق من حالة طلب، ثم يقرأ سياسة الإرجاع، ثم يجهّز استردادًا للمبلغ. استخدم الوكيل فقط حين لا يمكن تحديد الخطوات مسبقًا؛ فالمسار الثابت أرخص وأسهل اختبارًا كسير عمل عادي.',
                    'توصف كل أداة باسم وشرح ومخطط JSON Schema لمعاملاتها، مثل get_order(order_id: string). لا ينفذ النموذج الشيفرة بنفسه؛ بل يعيد استدعاءً منظمًا، فيتحقق التطبيق من المعاملات وينفذه، ثم تعود النتيجة إلى النموذج. يوحّد بروتوكول سياق النموذج (MCP) طريقة إتاحة التطبيقات للأدوات والبيانات أمام النماذج. كثيرًا ما تؤثر الأوصاف الواضحة للأدوات والمعاملات المتحقق منها ورسائل الخطأ المفيدة في نجاح الوكيل أكثر من اختيار النموذج.',
                    'الذاكرة قصيرة المدى هي سجل المحادثة داخل نافذة السياق؛ أما الذاكرة طويلة المدى فتُحفظ عادة في قاعدة بيانات أو مخزن متجهات وتُسترجع عند الحاجة. في المهام الطويلة يستطيع الوكيل تقسيم الهدف إلى خطة متدرجة وتحديثها بعد كل نتيجة. يوزّع نمط المنسق والعامل المهام الفرعية على عدة وكلاء يعملون بالتوازي، مثل البحث في عدة مصادر في آن واحد. كل وكيل إضافي يزيد تكلفة الرموز والتأخير ونقاط الفشل، لذا ابدأ بوكيل واحد بسيط.',
                    'قد يحتوي نص صفحات الويب أو الرسائل أو المستندات على حقن أوامر يطلب من الوكيل فعل شيء آخر. امنح الأدوات أقل صلاحيات ممكنة، وشغّل الشيفرة في بيئة معزولة، وحدّد عدد الخطوات والميزانية، واطلب موافقة بشرية قبل الأفعال التي يصعب التراجع عنها مثل تحويل الأموال أو حذف البيانات. احفظ سجلًا لكل خطوة لأغراض التدقيق. قيّم الوكلاء بمجموعة مهام حقيقية وقِس نسبة النجاح وعدد الخطوات والتكلفة والأخطاء الجسيمة؛ وتتبع معايير مثل SWE-bench وτ-bench النهج نفسه.']],
            17: ['RAG وتقييم تطبيقات النماذج اللغوية', 'اجعل إجابات النموذج اللغوي مستندة إلى مستنداتك، ثم قِس جودة الاسترجاع والإجابات بطريقة منهجية.',
                ['لماذا RAG', 'التقطيع والتضمين والبحث المتجهي', 'بناء الموجّه والاستشهادات', 'تقييم تطبيقات النماذج اللغوية'],
                ['لا يعرف النموذج اللغوي الكبير إلا بيانات تدريبه، وله تاريخ انقطاع معرفي، وقد يهلوس بثقة. يبحث التوليد المعزز بالاسترجاع (RAG) عن مقاطع المستندات ذات الصلة عند وصول السؤال ويضيفها إلى الموجّه، فيجيب النموذج اعتمادًا على تلك المصادر. يمكن تحديث المعرفة دون إعادة التدريب، ويمكن أن ترفق كل إجابة باستشهادات. يناسب الضبط الدقيق تغيير أسلوب الإجابة أو صيغتها، بينما يناسب RAG المعرفة التي تتغير كثيرًا مثل سياسات الشركة.',
                    'تُقسَّم المستندات إلى مقاطع من نحو 200 إلى 800 رمز مع تداخل بسيط حتى لا تفقد الجمل معناها. يحوّل نموذج التضمين كل مقطع إلى متجه يُحفظ في قاعدة بيانات متجهات مثل pgvector أو Qdrant أو FAISS. يُحوَّل السؤال أيضًا إلى متجه، ويسترجع النظام أعلى k مقاطع من حيث تشابه جيب التمام. يجمع البحث الهجين بين البحث المتجهي وBM25 للمصطلحات الدقيقة مثل رموز المنتجات، ثم يعيد نموذج إعادة الترتيب ترتيب المرشحين قبل إرسالهم إلى النموذج.',
                    'ضع المقاطع المختارة في الموجّه مع معرّفاتها وعناوين مصادرها، واطلب من النموذج أن يجيب من هذا السياق فقط، وأن يذكر المصادر مثل [doc-3]، وأن يقول "لا أعرف" إن لم تكن الإجابة موجودة. السياق الطويل جدًا يزيد التكلفة وقد يجعل النموذج يغفل المعلومات الواقعة في المنتصف، لذا أرسل المقاطع الأكثر صلة فقط. طبّق مرشحات البيانات الوصفية وصلاحيات الوصول أثناء الاسترجاع لا بعده، كي لا يتلقى المستخدم محتوى مستندات لا يحق له رؤيتها.',
                    'أنشئ مجموعة بيانات مرجعية تضم عشرات إلى مئات الأسئلة الحقيقية مع مستنداتها والإجابات الصحيحة. قِس الاسترجاع بمقياسي recall@k وMRR: هل استُرجع المقطع الصحيح أصلًا؟ وقِس الإجابات بالأمانة للمصدر (كل ادعاء مدعوم بالمصادر) وملاءمة الإجابة (تجيب فعلًا عن السؤال). يسرّع استخدام نموذج لغوي كمحكّم وفق معايير واضحة عملية التقييم، لكن عايره أولًا بتقييمات بشرية. شغّل هذه التقييمات في CI كلما تغيّر الموجّه أو النموذج أو خط المعالجة، وراقب زمن الاستجابة والتكلفة في بيئة الإنتاج.']],
            quiz: [
                'ما نمط الوكلاء الذي يناوب بين خطوات الاستدلال واستدعاء الأدوات؟',
                ['لماذا ينبغي للوكيل أن يطلب موافقة بشرية قبل رد المبلغ أو حذف البيانات؟', ['لتصبح الرموز أرخص', 'لأن الفعل يصعب التراجع عنه وقد يحفّزه حقن الأوامر', 'لأن النماذج اللغوية لا تقرأ JSON', 'كي يعيد النموذج تدريب نفسه تلقائيًا']],
                ['في RAG، ما وظيفة نموذج التضمين؟', ['ضغط الصور', 'تحويل النص إلى متجهات للعثور على المقاطع المتقاربة في المعنى', 'تشفير قاعدة البيانات', 'زيادة عدد معاملات النموذج اللغوي']],
                'ما المقياس الذي يتحقق من أن كل ادعاء في الإجابة مدعوم بالمستندات المصدر؟'
            ]
        },
        hi: {
            16: ['AI एजेंट: काम करने वाले मॉडल', 'समझें कि LLM कैसे चरणों की योजना बनाते हैं, टूल कॉल करते हैं और साफ़ सुरक्षा सीमाओं में काम पूरा करते हैं।',
                ['चैटबॉट से एजेंट तक', 'टूल कॉलिंग और फ़ंक्शन स्कीमा', 'मेमोरी, प्लानिंग और मल्टी-एजेंट', 'एजेंट की सुरक्षा और मूल्यांकन'],
                ['चैटबॉट एक संदेश का जवाब देकर रुक जाता है। एजेंट LLM को एक लूप में चलाता है: लक्ष्य पढ़ता है, एक कदम चुनता है, टूल कॉल करता है, नतीजा पढ़ता है और काम पूरा होने तक अगला कदम तय करता है। ReAct पैटर्न तर्क और कार्रवाई को बारी-बारी से चलाता है। उदाहरण: सपोर्ट एजेंट ऑर्डर की स्थिति देखता है, रिटर्न नीति पढ़ता है, फिर रिफ़ंड तैयार करता है। एजेंट तभी इस्तेमाल करें जब कदम पहले से तय न हो सकें; तय प्रवाह को सामान्य वर्कफ़्लो बनाना सस्ता और जाँचने में आसान है।',
                    'हर टूल का नाम, विवरण और उसके आर्गुमेंट के लिए JSON Schema होता है, जैसे get_order(order_id: string)। मॉडल खुद कोड नहीं चलाता; वह एक संरचित कॉल लौटाता है, ऐप्लिकेशन आर्गुमेंट जाँचकर उसे चलाता है और नतीजा मॉडल को वापस भेजता है। Model Context Protocol (MCP) मानकीकृत करता है कि ऐप्लिकेशन मॉडल को टूल और डेटा कैसे दें। साफ़ टूल विवरण, जाँचे गए आर्गुमेंट और उपयोगी एरर संदेश अक्सर मॉडल के चुनाव से ज़्यादा एजेंट की सफलता तय करते हैं।',
                    'शॉर्ट-टर्म मेमोरी कॉन्टेक्स्ट विंडो में बातचीत का इतिहास है; लॉन्ग-टर्म मेमोरी आमतौर पर डेटाबेस या वेक्टर स्टोर में रहती है और ज़रूरत पड़ने पर निकाली जाती है। लंबे कामों में एजेंट लक्ष्य को चरणबद्ध योजना में बाँट सकता है और हर नतीजे के बाद उसे अपडेट कर सकता है। ऑर्केस्ट्रेटर-वर्कर पैटर्न उप-कार्यों को समानांतर चलने वाले कई एजेंटों में बाँटता है, जैसे एक साथ कई स्रोतों पर शोध। हर अतिरिक्त एजेंट टोकन लागत, देरी और विफलता के बिंदु बढ़ाता है, इसलिए एक सरल एजेंट से शुरू करें।',
                    'वेब पेज, ईमेल या दस्तावेज़ के टेक्स्ट में प्रॉम्प्ट इंजेक्शन हो सकता है जो एजेंट से कुछ और करवाना चाहे। टूल को न्यूनतम अधिकार दें, कोड को सैंडबॉक्स में चलाएँ, कदमों और बजट की सीमा रखें, और पैसे ट्रांसफ़र करने या डेटा हटाने जैसे मुश्किल से पलटे जाने वाले कामों से पहले इंसान की मंज़ूरी लें। ऑडिट के लिए हर कदम का ट्रेस रखें। एजेंट को असली कार्यों के सेट पर परखें और सफलता दर, कदमों की संख्या, लागत और गंभीर गलतियाँ मापें; SWE-bench और τ-bench जैसे बेंचमार्क भी यही तरीका अपनाते हैं।']],
            17: ['RAG और LLM ऐप्लिकेशन का मूल्यांकन', 'LLM के जवाबों को अपने दस्तावेज़ों पर आधारित करें, फिर रिट्रीवल और जवाब की गुणवत्ता को व्यवस्थित ढंग से मापें।',
                ['RAG क्यों', 'चंकिंग, एम्बेडिंग और वेक्टर सर्च', 'प्रॉम्प्ट और संदर्भ बनाना', 'LLM ऐप्लिकेशन का मूल्यांकन'],
                ['LLM सिर्फ़ अपने ट्रेनिंग डेटा को जानता है, उसकी ज्ञान की एक कटऑफ़ तारीख होती है, और वह आत्मविश्वास से गलत बातें गढ़ सकता है। Retrieval-Augmented Generation (RAG) सवाल आने पर दस्तावेज़ों के प्रासंगिक अंश खोजता है और उन्हें प्रॉम्प्ट में जोड़ता है, ताकि मॉडल उन्हीं स्रोतों से जवाब दे। ज्ञान को दोबारा ट्रेनिंग के बिना अपडेट किया जा सकता है और हर जवाब के साथ संदर्भ दिए जा सकते हैं। फ़ाइन-ट्यूनिंग जवाब की शैली या फ़ॉर्मैट बदलने के लिए है; RAG बार-बार बदलने वाले ज्ञान, जैसे कंपनी की नीतियों, के लिए।',
                    'दस्तावेज़ों को लगभग 200 से 800 टोकन के चंक में बाँटा जाता है, थोड़े ओवरलैप के साथ ताकि वाक्यों का अर्थ न टूटे। एम्बेडिंग मॉडल हर चंक को वेक्टर में बदलता है, जिसे pgvector, Qdrant या FAISS जैसे वेक्टर डेटाबेस में रखा जाता है। सवाल को भी वेक्टर में बदला जाता है और सिस्टम सबसे ज़्यादा कोसाइन समानता वाले top-k चंक निकालता है। हाइब्रिड सर्च उत्पाद कोड जैसे सटीक शब्दों के लिए वेक्टर सर्च को BM25 के साथ जोड़ता है, और रीरैंकर मॉडल तक भेजने से पहले उम्मीदवारों को फिर से क्रम में लगाता है।',
                    'चुने गए चंक को उनकी ID और स्रोत के शीर्षक के साथ प्रॉम्प्ट में रखें, और मॉडल से कहें कि वह सिर्फ़ उसी संदर्भ से जवाब दे, [doc-3] जैसे स्रोत बताए और जवाब न मिलने पर "मुझे नहीं पता" कहे। बहुत लंबा संदर्भ ज़्यादा महँगा होता है और मॉडल बीच की जानकारी छोड़ सकता है, इसलिए सिर्फ़ सबसे प्रासंगिक चंक भेजें। मेटाडेटा और एक्सेस-कंट्रोल फ़िल्टर रिट्रीवल के दौरान ही लगाएँ, बाद में नहीं, ताकि उपयोगकर्ता को कभी ऐसे दस्तावेज़ की सामग्री न मिले जिसे देखने की उसे अनुमति नहीं।',
                    'दर्जनों से सैकड़ों असली सवालों का एक गोल्डन डेटासेट बनाएँ, उनके स्रोत दस्तावेज़ों और सही जवाबों के साथ। रिट्रीवल को recall@k और MRR से मापें: क्या सही चंक निकला भी? जवाबों को faithfulness (हर दावा स्रोत से समर्थित) और answer relevance (सच में सवाल का जवाब देता है) से मापें। साफ़ रूब्रिक वाला LLM-as-a-judge मूल्यांकन तेज़ करता है, लेकिन पहले उसे मानवीय रेटिंग से कैलिब्रेट करें। जब भी प्रॉम्प्ट, मॉडल या पाइपलाइन बदले, ये मूल्यांकन CI में चलाएँ और प्रोडक्शन में देरी और लागत पर नज़र रखें।']],
            quiz: [
                'कौन-सा एजेंट पैटर्न तर्क के चरणों और टूल कॉल को बारी-बारी से चलाता है?',
                ['रिफ़ंड देने या डेटा हटाने से पहले एजेंट को इंसान की मंज़ूरी क्यों लेनी चाहिए?', ['ताकि टोकन सस्ते हों', 'क्योंकि यह काम पलटना मुश्किल है और प्रॉम्प्ट इंजेक्शन से शुरू हो सकता है', 'क्योंकि LLM JSON नहीं पढ़ सकते', 'ताकि मॉडल खुद को दोबारा ट्रेन कर ले']],
                ['RAG में एम्बेडिंग मॉडल क्या करता है?', ['तस्वीरें संपीड़ित करता है', 'टेक्स्ट को वेक्टर में बदलता है ताकि मिलते-जुलते अर्थ वाले अंश खोजे जा सकें', 'डेटाबेस को एन्क्रिप्ट करता है', 'LLM में पैरामीटर जोड़ता है']],
                'कौन-सा मेट्रिक जाँचता है कि जवाब का हर दावा स्रोत दस्तावेज़ों से समर्थित है?'
            ]
        },
        pt: {
            16: ['Agentes de IA: Modelos que Agem', 'Entenda como os LLMs planejam etapas, chamam ferramentas e concluem tarefas dentro de limites de segurança claros.',
                ['Do Chatbot ao Agente', 'Chamada de Ferramentas e Esquemas de Funções', 'Memória, Planejamento e Multiagentes', 'Segurança e Avaliação de Agentes'],
                ['Um chatbot responde a uma mensagem e para. Um agente executa um LLM em loop: lê o objetivo, escolhe uma etapa, chama uma ferramenta, lê o resultado e decide a próxima etapa até concluir a tarefa. O padrão ReAct alterna raciocínio e ação. Exemplo: um agente de suporte consulta o status de um pedido, lê a política de devolução e prepara um reembolso. Use um agente só quando as etapas não puderem ser definidas de antemão; um fluxo fixo é mais barato e mais fácil de testar como workflow comum.',
                    'Cada ferramenta é descrita com um nome, uma explicação e um JSON Schema para os argumentos, por exemplo get_order(order_id: string). O modelo não executa código sozinho: ele devolve uma chamada estruturada, a aplicação valida os argumentos e a executa, e o resultado volta para o modelo. O Model Context Protocol (MCP) padroniza como as aplicações oferecem ferramentas e dados aos modelos. Descrições claras, argumentos validados e mensagens de erro informativas costumam pesar mais no sucesso do agente do que a escolha do modelo.',
                    'A memória de curto prazo é o histórico da conversa na janela de contexto; a de longo prazo costuma ficar num banco de dados ou vector store e é recuperada quando relevante. Em tarefas longas, o agente pode dividir o objetivo num plano por etapas e atualizá-lo após cada resultado. O padrão orquestrador-trabalhador distribui subtarefas entre vários agentes em paralelo, por exemplo pesquisando várias fontes ao mesmo tempo. Cada agente extra adiciona custo de tokens, latência e pontos de falha, então comece com um agente simples.',
                    'Texto de páginas web, e-mails ou documentos pode conter injeção de prompt que manda o agente fazer outra coisa. Dê às ferramentas o menor privilégio possível, rode código num sandbox, limite o número de etapas e o orçamento, e peça aprovação humana antes de ações difíceis de desfazer, como transferir dinheiro ou apagar dados. Guarde um rastro de cada etapa para auditoria. Avalie agentes com um conjunto de tarefas reais e meça taxa de sucesso, número de etapas, custo e erros graves; benchmarks como SWE-bench e τ-bench seguem a mesma abordagem.']],
            17: ['RAG e Avaliação de Aplicações LLM', 'Baseie as respostas do LLM nos seus próprios documentos e meça de forma sistemática a qualidade da recuperação e das respostas.',
                ['Por Que RAG', 'Chunking, Embeddings e Busca Vetorial', 'Montando o Prompt e as Citações', 'Avaliando Aplicações LLM'],
                ['Um LLM só conhece os dados de treino, tem uma data de corte e pode alucinar com confiança. A geração aumentada por recuperação (RAG) busca trechos relevantes de documentos quando chega uma pergunta e os insere no prompt, para que o modelo responda com base nessas fontes. O conhecimento pode ser atualizado sem retreinar, e cada resposta pode trazer citações. O fine-tuning serve para mudar o estilo ou o formato das respostas; o RAG serve para conhecimento que muda com frequência, como políticas da empresa.',
                    'Os documentos são divididos em chunks de cerca de 200 a 800 tokens com uma pequena sobreposição, para que as frases mantenham o sentido. Um modelo de embeddings transforma cada chunk num vetor, guardado num banco vetorial como pgvector, Qdrant ou FAISS. A pergunta também vira vetor, e o sistema recupera os top-k chunks com maior similaridade de cosseno. A busca híbrida combina vetores com BM25 para termos exatos, como códigos de produto, e um reranker reordena os candidatos antes de enviá-los ao modelo.',
                    'Coloque os chunks escolhidos no prompt com seus IDs e títulos de origem, e instrua o modelo a responder só com esse contexto, citar fontes como [doc-3] e dizer "não sei" quando a resposta não estiver lá. Contexto longo demais custa mais e pode fazer o modelo perder informações do meio, então envie só os chunks mais relevantes. Aplique filtros de metadados e de permissão durante a recuperação, não depois, para que ninguém receba conteúdo de documentos que não pode ver.',
                    'Monte um golden dataset com dezenas a centenas de perguntas reais, seus documentos de origem e as respostas corretas. Meça a recuperação com recall@k e MRR: o chunk certo foi recuperado? Meça as respostas com faithfulness (toda afirmação tem apoio nas fontes) e answer relevance (responde de fato à pergunta). Um LLM como juiz com rubrica clara acelera a avaliação, mas calibre-o antes com notas humanas. Rode essas avaliações no CI sempre que o prompt, o modelo ou o pipeline mudar, e monitore latência e custo em produção.']],
            quiz: [
                'Qual padrão de agente alterna etapas de raciocínio e chamadas de ferramentas?',
                ['Por que um agente deve pedir aprovação humana antes de fazer um reembolso ou apagar dados?', ['Para deixar os tokens mais baratos', 'Porque a ação é difícil de desfazer e pode ser disparada por injeção de prompt', 'Porque LLMs não leem JSON', 'Para o modelo se retreinar sozinho']],
                ['No RAG, o que faz o modelo de embeddings?', ['Comprime imagens', 'Transforma texto em vetores para encontrar trechos de significado parecido', 'Criptografa o banco de dados', 'Adiciona parâmetros ao LLM']],
                'Qual métrica verifica se cada afirmação de uma resposta é apoiada pelos documentos de origem?'
            ]
        },
        fr: {
            16: ['Agents IA : des Modèles qui Agissent', 'Comprendre comment les LLM planifient des étapes, appellent des outils et accomplissent des tâches dans des limites de sécurité claires.',
                ['Du Chatbot à l’Agent', 'Appels d’Outils et Schémas de Fonctions', 'Mémoire, Planification et Multi-Agents', 'Sécurité et Évaluation des Agents'],
                ['Un chatbot répond à un message puis s’arrête. Un agent fait tourner un LLM en boucle : il lit l’objectif, choisit une étape, appelle un outil, lit le résultat et décide de l’étape suivante jusqu’à la fin de la tâche. Le schéma ReAct alterne raisonnement et action. Exemple : un agent de support vérifie le statut d’une commande, lit la politique de retour, puis prépare un remboursement. N’utilisez un agent que si les étapes ne peuvent pas être fixées d’avance ; un flux fixe coûte moins cher et se teste plus facilement comme workflow classique.',
                    'Chaque outil est décrit par un nom, une explication et un JSON Schema pour ses arguments, par exemple get_order(order_id: string). Le modèle n’exécute pas de code lui-même : il renvoie un appel structuré, l’application valide les arguments et l’exécute, puis le résultat revient au modèle. Le Model Context Protocol (MCP) standardise la façon dont les applications exposent outils et données aux modèles. Des descriptions claires, des arguments validés et des messages d’erreur utiles comptent souvent plus pour la réussite d’un agent que le choix du modèle.',
                    'La mémoire à court terme est l’historique de la conversation dans la fenêtre de contexte ; la mémoire à long terme est en général stockée dans une base de données ou un vector store et récupérée quand elle est utile. Pour les tâches longues, l’agent peut découper l’objectif en plan par étapes et le mettre à jour après chaque résultat. Le schéma orchestrateur-exécutants confie des sous-tâches à plusieurs agents en parallèle, par exemple pour explorer plusieurs sources à la fois. Chaque agent supplémentaire ajoute coût en tokens, latence et points de défaillance : commencez par un seul agent simple.',
                    'Le texte de pages web, d’e-mails ou de documents peut contenir une injection de prompt qui pousse l’agent à faire autre chose. Donnez aux outils le moins de privilèges possible, exécutez le code dans un bac à sable, plafonnez le nombre d’étapes et le budget, et exigez une validation humaine avant les actions difficiles à annuler comme un virement ou une suppression de données. Conservez une trace de chaque étape pour l’audit. Évaluez les agents sur un ensemble de tâches réelles en mesurant le taux de réussite, le nombre d’étapes, le coût et les erreurs graves ; des benchmarks comme SWE-bench et τ-bench suivent la même logique.']],
            17: ['RAG et Évaluation des Applications LLM', 'Ancrer les réponses d’un LLM dans vos propres documents, puis mesurer systématiquement la qualité de la recherche et des réponses.',
                ['Pourquoi le RAG', 'Découpage, Embeddings et Recherche Vectorielle', 'Construire le Prompt et les Citations', 'Évaluer les Applications LLM'],
                ['Un LLM ne connaît que ses données d’entraînement, a une date limite de connaissances et peut halluciner avec aplomb. La génération augmentée par récupération (RAG) cherche les passages pertinents de vos documents à l’arrivée d’une question et les insère dans le prompt, pour que le modèle réponde à partir de ces sources. Les connaissances se mettent à jour sans réentraînement et chaque réponse peut citer ses sources. Le fine-tuning sert à changer le style ou le format des réponses ; le RAG convient aux connaissances qui évoluent souvent, comme les politiques d’une entreprise.',
                    'Les documents sont découpés en chunks d’environ 200 à 800 tokens avec un léger chevauchement pour que les phrases gardent leur sens. Un modèle d’embeddings transforme chaque chunk en vecteur, stocké dans une base vectorielle comme pgvector, Qdrant ou FAISS. La question est elle aussi vectorisée, et le système récupère les k chunks à la plus forte similarité cosinus. La recherche hybride combine vecteurs et BM25 pour les termes exacts comme les références produit, puis un reranker réordonne les candidats avant de les envoyer au modèle.',
                    'Placez les chunks retenus dans le prompt avec leur identifiant et le titre de leur source, puis demandez au modèle de répondre uniquement à partir de ce contexte, de citer ses sources comme [doc-3] et de dire « je ne sais pas » si la réponse n’y figure pas. Un contexte trop long coûte plus cher et peut faire manquer au modèle les informations du milieu : n’envoyez que les chunks les plus pertinents. Appliquez les filtres de métadonnées et de droits d’accès pendant la recherche, pas après, pour qu’aucun utilisateur ne reçoive le contenu d’un document qu’il n’a pas le droit de voir.',
                    'Constituez un golden dataset de quelques dizaines à quelques centaines de vraies questions, avec leurs documents sources et les bonnes réponses. Mesurez la recherche avec recall@k et MRR : le bon chunk a-t-il seulement été récupéré ? Mesurez les réponses avec la fidélité (chaque affirmation est appuyée par les sources) et la pertinence de la réponse (elle répond vraiment à la question). Un LLM juge avec une grille claire accélère la notation, mais calibrez-le d’abord sur des notes humaines. Lancez ces évaluations en CI à chaque changement de prompt, de modèle ou de pipeline, et surveillez latence et coût en production.']],
            quiz: [
                'Quel schéma d’agent alterne étapes de raisonnement et appels d’outils ?',
                ['Pourquoi un agent doit-il demander l’accord d’un humain avant un remboursement ou une suppression de données ?', ['Pour que les tokens coûtent moins cher', 'Parce que l’action est difficile à annuler et peut être déclenchée par une injection de prompt', 'Parce que les LLM ne savent pas lire le JSON', 'Pour que le modèle se réentraîne tout seul']],
                ['Dans le RAG, à quoi sert le modèle d’embeddings ?', ['À compresser des images', 'À transformer le texte en vecteurs pour retrouver des passages de sens proche', 'À chiffrer la base de données', 'À ajouter des paramètres au LLM']],
                'Quelle métrique vérifie que chaque affirmation d’une réponse est appuyée par les documents sources ?'
            ]
        },
        de: {
            16: ['KI-Agenten: Modelle, die handeln', 'Verstehen, wie LLMs Schritte planen, Tools aufrufen und Aufgaben innerhalb klarer Sicherheitsgrenzen erledigen.',
                ['Vom Chatbot zum Agenten', 'Tool Calling und Funktionsschemas', 'Gedächtnis, Planung und Multi-Agenten', 'Sicherheit und Bewertung von Agenten'],
                ['Ein Chatbot beantwortet eine Nachricht und hört auf. Ein Agent lässt ein LLM in einer Schleife laufen: Er liest das Ziel, wählt einen Schritt, ruft ein Tool auf, liest das Ergebnis und entscheidet über den nächsten Schritt, bis die Aufgabe erledigt ist. Das ReAct-Muster wechselt zwischen Denken und Handeln. Beispiel: Ein Support-Agent prüft den Bestellstatus, liest die Rückgaberichtlinie und bereitet eine Erstattung vor. Setzen Sie Agenten nur ein, wenn sich die Schritte nicht vorab festlegen lassen; ein fester Ablauf ist als normaler Workflow günstiger und leichter zu testen.',
                    'Jedes Tool wird mit einem Namen, einer Erklärung und einem JSON Schema für seine Argumente beschrieben, etwa get_order(order_id: string). Das Modell führt selbst keinen Code aus: Es gibt einen strukturierten Aufruf zurück, die Anwendung prüft die Argumente und führt ihn aus, und das Ergebnis geht zurück an das Modell. Das Model Context Protocol (MCP) standardisiert, wie Anwendungen Modellen Tools und Daten bereitstellen. Klare Tool-Beschreibungen, geprüfte Argumente und aussagekräftige Fehlermeldungen entscheiden oft mehr über den Erfolg als die Modellwahl.',
                    'Das Kurzzeitgedächtnis ist der Gesprächsverlauf im Kontextfenster; das Langzeitgedächtnis liegt meist in einer Datenbank oder einem Vector Store und wird bei Bedarf abgerufen. Bei langen Aufgaben kann ein Agent das Ziel in einen Schritt-für-Schritt-Plan zerlegen und ihn nach jedem Ergebnis anpassen. Das Orchestrator-Worker-Muster verteilt Teilaufgaben auf mehrere parallel arbeitende Agenten, etwa um mehrere Quellen gleichzeitig zu recherchieren. Jeder zusätzliche Agent erhöht Token-Kosten, Latenz und Fehlerquellen, also beginnen Sie mit einem einfachen Agenten.',
                    'Text aus Webseiten, E-Mails oder Dokumenten kann Prompt Injection enthalten, die den Agenten zu etwas anderem verleitet. Geben Sie Tools möglichst wenige Rechte, führen Sie Code in einer Sandbox aus, begrenzen Sie Schritte und Budget, und holen Sie vor schwer umkehrbaren Aktionen wie Überweisungen oder dem Löschen von Daten eine menschliche Freigabe ein. Protokollieren Sie jeden Schritt für Audits. Bewerten Sie Agenten anhand realer Aufgaben und messen Sie Erfolgsquote, Schrittzahl, Kosten und schwere Fehler; Benchmarks wie SWE-bench und τ-bench gehen genauso vor.']],
            17: ['RAG und Bewertung von LLM-Anwendungen', 'LLM-Antworten auf die eigenen Dokumente stützen und die Qualität von Retrieval und Antworten systematisch messen.',
                ['Warum RAG', 'Chunking, Embeddings und Vektorsuche', 'Prompt und Quellenangaben aufbauen', 'LLM-Anwendungen bewerten'],
                ['Ein LLM kennt nur seine Trainingsdaten, hat einen Wissensstichtag und kann selbstbewusst halluzinieren. Retrieval-Augmented Generation (RAG) sucht beim Eingang einer Frage passende Dokumentabschnitte und fügt sie in den Prompt ein, damit das Modell auf Basis dieser Quellen antwortet. Wissen lässt sich ohne Neutraining aktualisieren, und jede Antwort kann Quellen nennen. Fine-Tuning eignet sich, um Stil oder Format zu ändern; RAG eignet sich für Wissen, das sich oft ändert, etwa Unternehmensrichtlinien.',
                    'Dokumente werden in Chunks von etwa 200 bis 800 Tokens mit etwas Überlappung zerlegt, damit Sätze ihren Sinn behalten. Ein Embedding-Modell wandelt jeden Chunk in einen Vektor um, der in einer Vektordatenbank wie pgvector, Qdrant oder FAISS gespeichert wird. Auch die Frage wird eingebettet, und das System holt die Top-k-Chunks mit der höchsten Kosinus-Ähnlichkeit. Hybride Suche kombiniert Vektorsuche mit BM25 für exakte Begriffe wie Produktcodes, und ein Reranker sortiert die Kandidaten neu, bevor sie an das Modell gehen.',
                    'Fügen Sie die ausgewählten Chunks mit ID und Quelltitel in den Prompt ein und weisen Sie das Modell an, nur aus diesem Kontext zu antworten, Quellen wie [doc-3] zu nennen und „weiß ich nicht“ zu sagen, wenn die Antwort fehlt. Sehr langer Kontext kostet mehr und kann dazu führen, dass Informationen in der Mitte übersehen werden; senden Sie daher nur die relevantesten Chunks. Wenden Sie Metadaten- und Zugriffsfilter beim Retrieval an, nicht danach, damit niemand Inhalte aus Dokumenten erhält, die er nicht sehen darf.',
                    'Erstellen Sie einen Golden Dataset mit Dutzenden bis Hunderten echter Fragen samt Quelldokumenten und richtigen Antworten. Messen Sie das Retrieval mit Recall@k und MRR: Wurde der richtige Chunk überhaupt gefunden? Messen Sie Antworten mit Faithfulness (jede Aussage ist durch Quellen belegt) und Answer Relevance (die Frage wird wirklich beantwortet). LLM-as-a-Judge mit klarer Bewertungsskala beschleunigt die Bewertung, sollte aber zuerst an menschlichen Urteilen kalibriert werden. Führen Sie diese Bewertungen in CI aus, sobald sich Prompt, Modell oder Pipeline ändern, und überwachen Sie Latenz und Kosten in Produktion.']],
            quiz: [
                'Welches Agentenmuster wechselt zwischen Denkschritten und Tool-Aufrufen?',
                ['Warum sollte ein Agent vor einer Erstattung oder dem Löschen von Daten eine menschliche Freigabe einholen?', ['Damit Tokens billiger werden', 'Weil die Aktion schwer rückgängig zu machen ist und durch Prompt Injection ausgelöst werden könnte', 'Weil LLMs kein JSON lesen können', 'Damit sich das Modell selbst neu trainiert']],
                ['Was macht das Embedding-Modell bei RAG?', ['Es komprimiert Bilder', 'Es wandelt Text in Vektoren um, damit Abschnitte mit ähnlicher Bedeutung gefunden werden', 'Es verschlüsselt die Datenbank', 'Es fügt dem LLM Parameter hinzu']],
                'Welche Metrik prüft, ob jede Aussage einer Antwort durch die Quelldokumente belegt ist?'
            ]
        },
        ja: {
            16: ['AIエージェント：行動するモデル', 'LLMが手順を計画し、ツールを呼び出し、明確な安全範囲の中でタスクを完了する仕組みを理解します。',
                ['チャットボットからエージェントへ', 'ツール呼び出しと関数スキーマ', 'メモリ、計画、マルチエージェント', 'エージェントの安全性と評価'],
                ['チャットボットは1つのメッセージに答えて終わります。エージェントはLLMをループの中で動かします。目標を読み、手順を選び、ツールを呼び出し、結果を読んで、タスクが終わるまで次の手順を決めます。ReActパターンは推論と行動を交互に行います。例えばサポート用エージェントは、注文状況を確認し、返品ポリシーを読み、返金を準備します。手順を事前に決められない場合だけエージェントを使いましょう。決まった流れなら通常のワークフローの方が安く、テストも簡単です。',
                    '各ツールは名前、説明、引数のJSON Schemaで記述します。例えばget_order(order_id: string)です。モデルが自らコードを実行することはありません。構造化された呼び出しを返し、アプリケーションが引数を検証して実行し、その結果をモデルに戻します。Model Context Protocol（MCP）は、アプリケーションがモデルにツールやデータを提供する方法を標準化します。分かりやすいツールの説明、検証済みの引数、役に立つエラーメッセージは、モデルの選択以上にエージェントの成否を左右することがよくあります。',
                    '短期記憶はコンテキストウィンドウ内の会話履歴です。長期記憶は通常データベースやベクトルストアに保存し、必要なときに取り出します。長いタスクでは、エージェントが目標を段階的な計画に分解し、結果が出るたびに更新できます。オーケストレーター・ワーカー型は、サブタスクを並列に動く複数のエージェントに割り振ります。例えば複数の情報源を同時に調べる場合です。エージェントを1つ増やすごとにトークン費用、遅延、故障点が増えるので、まずはシンプルな1つのエージェントから始めましょう。',
                    'Webページ、メール、文書のテキストには、エージェントに別のことをさせようとするプロンプトインジェクションが含まれている場合があります。ツールの権限は最小限にし、コードはサンドボックスで実行し、手順数と予算に上限を設け、送金やデータ削除のように取り消しにくい操作の前には人間の承認を求めましょう。監査のために各手順のトレースを残します。エージェントは実際のタスク集合で評価し、成功率、手順数、コスト、重大なエラーを測ります。SWE-benchやτ-benchなどのベンチマークも同じ考え方です。']],
            17: ['RAGとLLMアプリケーションの評価', 'LLMの回答を自分の文書に基づかせ、検索と回答の品質を体系的に測定します。',
                ['なぜRAGなのか', 'チャンク分割、埋め込み、ベクトル検索', 'プロンプトと出典の組み立て', 'LLMアプリケーションの評価'],
                ['LLMは学習データの内容しか知らず、知識の締め切り日があり、自信満々にハルシネーションを起こすこともあります。検索拡張生成（RAG）は、質問が来たときに関連する文書の断片を探してプロンプトに挿入し、モデルがその情報源に基づいて答えるようにします。再学習なしで知識を更新でき、各回答に出典を付けられます。ファインチューニングは回答のスタイルや形式を変えるのに向き、RAGは社内規程のように頻繁に変わる知識に向いています。',
                    '文書は、文の意味が途切れないよう少し重なりを持たせて、約200〜800トークンのチャンクに分割します。埋め込みモデルが各チャンクをベクトルに変換し、pgvector、Qdrant、FAISSなどのベクトルデータベースに保存します。質問もベクトルに変換し、コサイン類似度が最も高い上位k個のチャンクを取り出します。ハイブリッド検索は、製品コードのような完全一致の語に強いBM25とベクトル検索を組み合わせ、リランカーが候補を並べ直してからモデルに渡します。',
                    '選んだチャンクをIDと出典タイトル付きでプロンプトに入れ、その文脈だけから答えること、[doc-3]のように出典を示すこと、答えがなければ「分かりません」と言うことをモデルに指示します。文脈が長すぎるとコストが増え、真ん中の情報を見落としやすくなるので、最も関連性の高いチャンクだけを送ります。メタデータやアクセス権によるフィルタは検索の後ではなく検索時に適用し、閲覧権限のない文書の内容が利用者に渡らないようにします。',
                    '実際の質問を数十〜数百件集め、出典文書と正解を付けたゴールデンデータセットを作ります。検索はrecall@kとMRRで測ります。正しいチャンクがそもそも取り出せたか、という観点です。回答は、忠実性（すべての主張が出典に裏付けられているか）と回答の関連性（質問に本当に答えているか）で測ります。明確な評価基準を持つLLM-as-a-judgeは採点を速くしますが、まず人間の評価で較正しましょう。プロンプト、モデル、パイプラインを変えるたびにCIでこれらの評価を実行し、本番では遅延とコストを監視します。']],
            quiz: [
                '推論のステップとツール呼び出しを交互に行うエージェントのパターンはどれですか？',
                ['返金やデータ削除の前に、エージェントが人間の承認を求めるべき理由は？', ['トークンを安くするため', '取り消しにくい操作であり、プロンプトインジェクションで引き起こされる恐れがあるため', 'LLMはJSONを読めないため', 'モデルを自動で再学習させるため']],
                ['RAGにおける埋め込みモデルの役割は？', ['画像を圧縮する', 'テキストをベクトルに変換し、意味の近い断片を探せるようにする', 'データベースを暗号化する', 'LLMのパラメータを増やす']],
                '回答のすべての主張が出典文書に裏付けられているかを確認する指標はどれですか？'
            ]
        },
        ko: {
            16: ['AI 에이전트: 행동하는 모델', 'LLM이 단계를 계획하고 도구를 호출하며 명확한 안전 범위 안에서 작업을 끝내는 방법을 이해합니다.',
                ['챗봇에서 에이전트로', '도구 호출과 함수 스키마', '메모리, 계획, 멀티 에이전트', '에이전트의 안전과 평가'],
                ['챗봇은 메시지 하나에 답하고 멈춥니다. 에이전트는 LLM을 루프 안에서 실행합니다. 목표를 읽고, 단계를 고르고, 도구를 호출하고, 결과를 읽은 뒤 작업이 끝날 때까지 다음 단계를 정합니다. ReAct 패턴은 추론과 행동을 번갈아 수행합니다. 예를 들어 고객지원 에이전트는 주문 상태를 확인하고, 반품 정책을 읽은 뒤, 환불을 준비합니다. 단계를 미리 정할 수 없을 때만 에이전트를 쓰세요. 정해진 흐름이라면 일반 워크플로가 더 싸고 테스트하기도 쉽습니다.',
                    '각 도구는 이름, 설명, 인자에 대한 JSON Schema로 기술합니다. 예: get_order(order_id: string). 모델은 코드를 직접 실행하지 않습니다. 구조화된 호출을 반환하면 애플리케이션이 인자를 검증해 실행하고, 그 결과를 다시 모델에 보냅니다. Model Context Protocol(MCP)은 애플리케이션이 모델에 도구와 데이터를 제공하는 방식을 표준화합니다. 명확한 도구 설명, 검증된 인자, 유용한 오류 메시지가 모델 선택보다 에이전트의 성패를 더 크게 좌우하는 경우가 많습니다.',
                    '단기 메모리는 컨텍스트 윈도우 안의 대화 기록이고, 장기 메모리는 보통 데이터베이스나 벡터 스토어에 저장했다가 필요할 때 불러옵니다. 긴 작업에서는 에이전트가 목표를 단계별 계획으로 나누고 결과가 나올 때마다 갱신할 수 있습니다. 오케스트레이터-워커 패턴은 하위 작업을 병렬로 일하는 여러 에이전트에게 나눠 줍니다. 예를 들어 여러 출처를 동시에 조사하는 경우입니다. 에이전트가 하나 늘 때마다 토큰 비용, 지연, 실패 지점이 늘어나므로 단순한 에이전트 하나로 시작하세요.',
                    '웹 페이지, 이메일, 문서의 텍스트에는 에이전트에게 다른 일을 시키는 프롬프트 인젝션이 숨어 있을 수 있습니다. 도구에는 최소한의 권한만 주고, 코드는 샌드박스에서 실행하고, 단계 수와 예산에 상한을 두고, 송금이나 데이터 삭제처럼 되돌리기 어려운 작업 전에는 사람의 승인을 받으세요. 감사를 위해 모든 단계의 트레이스를 남깁니다. 에이전트는 실제 작업 모음으로 평가하고 성공률, 단계 수, 비용, 치명적 오류를 측정합니다. SWE-bench와 τ-bench 같은 벤치마크도 같은 접근을 씁니다.']],
            17: ['RAG와 LLM 애플리케이션 평가', 'LLM의 답변을 내 문서에 근거하게 하고, 검색과 답변의 품질을 체계적으로 측정합니다.',
                ['왜 RAG인가', '청킹, 임베딩, 벡터 검색', '프롬프트와 출처 구성하기', 'LLM 애플리케이션 평가하기'],
                ['LLM은 학습 데이터에 있는 내용만 알고, 지식 기준일이 있으며, 자신 있게 환각을 일으킬 수 있습니다. 검색 증강 생성(RAG)은 질문이 들어오면 관련 문서 조각을 찾아 프롬프트에 넣어, 모델이 그 출처를 바탕으로 답하게 합니다. 재학습 없이 지식을 갱신할 수 있고, 모든 답변에 출처를 붙일 수 있습니다. 파인튜닝은 답변의 스타일이나 형식을 바꾸는 데 적합하고, RAG는 회사 정책처럼 자주 바뀌는 지식에 적합합니다.',
                    '문서는 문장의 의미가 끊기지 않도록 약간 겹치게 해서 약 200~800 토큰 크기의 청크로 나눕니다. 임베딩 모델이 각 청크를 벡터로 바꾸고, pgvector, Qdrant, FAISS 같은 벡터 데이터베이스에 저장합니다. 질문도 벡터로 바꾼 뒤 코사인 유사도가 가장 높은 상위 k개 청크를 가져옵니다. 하이브리드 검색은 제품 코드처럼 정확한 용어를 위해 벡터 검색과 BM25를 결합하고, 리랭커가 후보를 다시 정렬한 뒤 모델에 보냅니다.',
                    '선택한 청크를 ID와 출처 제목과 함께 프롬프트에 넣고, 그 맥락만으로 답할 것, [doc-3]처럼 출처를 밝힐 것, 답이 없으면 "모르겠습니다"라고 말할 것을 모델에 지시합니다. 맥락이 너무 길면 비용이 늘고 중간에 있는 정보를 놓치기 쉬우므로 가장 관련성 높은 청크만 보내세요. 메타데이터와 접근 권한 필터는 검색 뒤가 아니라 검색할 때 적용해서, 사용자가 볼 권한이 없는 문서 내용을 절대 받지 않게 합니다.',
                    '실제 질문 수십~수백 개와 그 출처 문서, 정답으로 골든 데이터셋을 만드세요. 검색은 recall@k와 MRR로 측정합니다. 올바른 청크가 아예 검색되었는지를 보는 것입니다. 답변은 충실성(모든 주장이 출처로 뒷받침되는가)과 답변 관련성(정말 질문에 답하는가)으로 측정합니다. 명확한 루브릭을 갖춘 LLM-as-a-judge는 채점을 빠르게 하지만, 먼저 사람의 평가로 보정하세요. 프롬프트, 모델, 파이프라인이 바뀔 때마다 CI에서 이 평가를 실행하고, 운영 환경에서는 지연 시간과 비용을 모니터링합니다.']],
            quiz: [
                '추론 단계와 도구 호출을 번갈아 수행하는 에이전트 패턴은 무엇입니까?',
                ['환불이나 데이터 삭제 전에 에이전트가 사람의 승인을 받아야 하는 이유는?', ['토큰을 더 싸게 하려고', '되돌리기 어려운 작업이고 프롬프트 인젝션으로 실행될 수 있어서', 'LLM이 JSON을 읽지 못해서', '모델이 스스로 재학습하도록']],
                ['RAG에서 임베딩 모델의 역할은?', ['이미지를 압축한다', '텍스트를 벡터로 바꿔 의미가 비슷한 조각을 찾을 수 있게 한다', '데이터베이스를 암호화한다', 'LLM의 파라미터를 늘린다']],
                '답변의 모든 주장이 출처 문서로 뒷받침되는지 확인하는 지표는 무엇입니까?'
            ]
        },
        ru: {
            16: ['ИИ-агенты: модели, которые действуют', 'Как LLM планируют шаги, вызывают инструменты и выполняют задачи в чётких границах безопасности.',
                ['От чат-бота к агенту', 'Вызов инструментов и схемы функций', 'Память, планирование и мультиагентность', 'Безопасность и оценка агентов'],
                ['Чат-бот отвечает на одно сообщение и останавливается. Агент запускает LLM в цикле: читает цель, выбирает шаг, вызывает инструмент, читает результат и решает, что делать дальше, пока задача не выполнена. Паттерн ReAct чередует рассуждение и действие. Пример: агент поддержки проверяет статус заказа, читает правила возврата и готовит возврат денег. Используйте агента, только когда шаги нельзя задать заранее; фиксированный процесс дешевле и проще тестировать как обычный workflow.',
                    'Каждый инструмент описывается именем, пояснением и JSON Schema для аргументов, например get_order(order_id: string). Модель сама не выполняет код: она возвращает структурированный вызов, приложение проверяет аргументы и выполняет его, а результат возвращается модели. Model Context Protocol (MCP) стандартизирует то, как приложения предоставляют моделям инструменты и данные. Понятные описания инструментов, проверенные аргументы и информативные сообщения об ошибках часто важнее для успеха агента, чем выбор модели.',
                    'Кратковременная память — это история диалога в контекстном окне; долговременная обычно хранится в базе данных или векторном хранилище и извлекается по необходимости. В длинных задачах агент может разбить цель на пошаговый план и обновлять его после каждого результата. Паттерн оркестратор-исполнители раздаёт подзадачи нескольким агентам, работающим параллельно, например для одновременного изучения нескольких источников. Каждый новый агент добавляет стоимость токенов, задержку и точки отказа, поэтому начинайте с одного простого агента.',
                    'Текст веб-страниц, писем или документов может содержать промпт-инъекцию, которая заставляет агента делать что-то другое. Давайте инструментам минимум прав, запускайте код в песочнице, ограничивайте число шагов и бюджет и запрашивайте подтверждение человека перед трудно обратимыми действиями, такими как перевод денег или удаление данных. Сохраняйте трассировку каждого шага для аудита. Оценивайте агентов на наборе реальных задач и измеряйте долю успехов, число шагов, стоимость и критические ошибки; бенчмарки SWE-bench и τ-bench устроены так же.']],
            17: ['RAG и оценка LLM-приложений', 'Как опереть ответы LLM на ваши документы и системно измерять качество поиска и ответов.',
                ['Зачем нужен RAG', 'Чанкинг, эмбеддинги и векторный поиск', 'Сборка промпта и ссылки на источники', 'Оценка LLM-приложений'],
                ['LLM знает только свои обучающие данные, имеет дату отсечения знаний и может уверенно галлюцинировать. Генерация с дополненной выборкой (RAG) при поступлении вопроса ищет релевантные фрагменты документов и вставляет их в промпт, чтобы модель отвечала по этим источникам. Знания можно обновлять без переобучения, а каждый ответ может содержать ссылки. Fine-tuning подходит для изменения стиля или формата ответов; RAG подходит для часто меняющихся знаний, например правил компании.',
                    'Документы делят на чанки примерно по 200–800 токенов с небольшим перекрытием, чтобы предложения не теряли смысл. Модель эмбеддингов превращает каждый чанк в вектор, который хранится в векторной базе вроде pgvector, Qdrant или FAISS. Вопрос тоже превращается в вектор, и система извлекает top-k чанков с наибольшим косинусным сходством. Гибридный поиск сочетает векторы с BM25 для точных терминов, например артикулов, а реранкер переупорядочивает кандидатов перед отправкой модели.',
                    'Поместите выбранные чанки в промпт вместе с их ID и названиями источников и попросите модель отвечать только по этому контексту, ссылаться на источники вида [doc-3] и говорить «не знаю», если ответа там нет. Слишком длинный контекст дороже и может привести к тому, что модель пропустит информацию из середины, поэтому отправляйте только самые релевантные чанки. Применяйте фильтры по метаданным и правам доступа во время поиска, а не после, чтобы пользователь никогда не получил содержимое документов, которые ему видеть нельзя.',
                    'Соберите эталонный набор из десятков или сотен реальных вопросов с исходными документами и правильными ответами. Оценивайте поиск метриками recall@k и MRR: нашёлся ли нужный чанк вообще? Оценивайте ответы по faithfulness (каждое утверждение подкреплено источниками) и answer relevance (ответ действительно отвечает на вопрос). LLM в роли судьи с понятной рубрикой ускоряет оценку, но сначала откалибруйте его по оценкам людей. Запускайте эти проверки в CI при каждом изменении промпта, модели или пайплайна и следите за задержкой и стоимостью в продакшене.']],
            quiz: [
                'Какой паттерн агентов чередует шаги рассуждения и вызовы инструментов?',
                ['Почему агенту стоит запрашивать подтверждение человека перед возвратом денег или удалением данных?', ['Чтобы токены стали дешевле', 'Потому что действие трудно отменить и его может вызвать промпт-инъекция', 'Потому что LLM не умеют читать JSON', 'Чтобы модель сама себя переобучила']],
                ['Что делает модель эмбеддингов в RAG?', ['Сжимает изображения', 'Превращает текст в векторы, чтобы находить фрагменты с похожим смыслом', 'Шифрует базу данных', 'Добавляет параметры в LLM']],
                'Какая метрика проверяет, что каждое утверждение в ответе подкреплено исходными документами?'
            ]
        },
        tr: {
            16: ['Yapay Zekâ Ajanları: Harekete Geçen Modeller', 'LLM’lerin adımları nasıl planladığını, araçları nasıl çağırdığını ve görevleri net güvenlik sınırları içinde nasıl tamamladığını anlayın.',
                ['Sohbet Botundan Ajana', 'Araç Çağırma ve Fonksiyon Şemaları', 'Bellek, Planlama ve Çoklu Ajanlar', 'Ajan Güvenliği ve Değerlendirmesi'],
                ['Bir sohbet botu tek bir mesaja yanıt verir ve durur. Ajan ise bir LLM’i döngü içinde çalıştırır: hedefi okur, bir adım seçer, bir araç çağırır, sonucu okur ve görev bitene kadar sonraki adıma karar verir. ReAct deseni akıl yürütme ile eylemi dönüşümlü yürütür. Örnek: bir destek ajanı sipariş durumunu kontrol eder, iade politikasını okur ve ardından iadeyi hazırlar. Ajanı yalnızca adımlar önceden belirlenemiyorsa kullanın; sabit bir akış, sıradan bir iş akışı olarak daha ucuz ve test etmesi daha kolaydır.',
                    'Her araç bir ad, bir açıklama ve argümanları için bir JSON Schema ile tanımlanır, örneğin get_order(order_id: string). Model kodu kendisi çalıştırmaz; yapılandırılmış bir çağrı döndürür, uygulama argümanları doğrulayıp çalıştırır ve sonuç modele geri gönderilir. Model Context Protocol (MCP), uygulamaların modellere araç ve veri sunma biçimini standartlaştırır. Açık araç tanımları, doğrulanmış argümanlar ve bilgilendirici hata mesajları çoğu zaman ajanın başarısını model seçiminden daha çok belirler.',
                    'Kısa süreli bellek, bağlam penceresindeki konuşma geçmişidir; uzun süreli bellek genellikle bir veritabanında ya da vektör deposunda tutulur ve gerektiğinde geri getirilir. Uzun görevlerde ajan hedefi adım adım bir plana bölebilir ve her sonuçtan sonra planı güncelleyebilir. Orkestratör-işçi deseni alt görevleri paralel çalışan birkaç ajana dağıtır; örneğin birden fazla kaynağı aynı anda araştırmak için. Her ek ajan token maliyetini, gecikmeyi ve hata noktalarını artırır; bu yüzden tek ve basit bir ajanla başlayın.',
                    'Web sayfalarındaki, e-postalardaki veya belgelerdeki metinler, ajana başka bir şey yaptırmaya çalışan prompt enjeksiyonu içerebilir. Araçlara mümkün olan en az yetkiyi verin, kodu sandbox içinde çalıştırın, adım sayısını ve bütçeyi sınırlayın; para transferi ya da veri silme gibi geri alınması zor işlemlerden önce insan onayı isteyin. Denetim için her adımın izini saklayın. Ajanları gerçek görevlerden oluşan bir set üzerinde değerlendirip başarı oranını, adım sayısını, maliyeti ve kritik hataları ölçün; SWE-bench ve τ-bench gibi kıyaslamalar da aynı yaklaşımı kullanır.']],
            17: ['RAG ve LLM Uygulamalarının Değerlendirilmesi', 'LLM yanıtlarını kendi belgelerinize dayandırın, ardından erişim ve yanıt kalitesini sistemli biçimde ölçün.',
                ['Neden RAG', 'Parçalama, Embedding ve Vektör Arama', 'Prompt’u ve Kaynakları Oluşturmak', 'LLM Uygulamalarını Değerlendirmek'],
                ['Bir LLM yalnızca eğitim verisini bilir, bir bilgi kesim tarihi vardır ve kendinden emin biçimde halüsinasyon görebilir. Erişimle Güçlendirilmiş Üretim (RAG), bir soru geldiğinde ilgili belge parçalarını bulur ve prompt’a ekler; böylece model bu kaynaklara dayanarak yanıt verir. Bilgi yeniden eğitim olmadan güncellenebilir ve her yanıt kaynak gösterebilir. Fine-tuning yanıtın üslubunu ya da biçimini değiştirmek için uygundur; RAG ise şirket politikaları gibi sık değişen bilgiler için uygundur.',
                    'Belgeler, cümlelerin anlamı bozulmasın diye biraz örtüşmeyle yaklaşık 200 ile 800 token’lık parçalara bölünür. Bir embedding modeli her parçayı vektöre dönüştürür ve bu vektör pgvector, Qdrant veya FAISS gibi bir vektör veritabanında saklanır. Soru da vektöre dönüştürülür ve sistem kosinüs benzerliği en yüksek top-k parçayı getirir. Hibrit arama, ürün kodları gibi birebir terimler için vektör aramayı BM25 ile birleştirir; ardından bir yeniden sıralayıcı adayları modele göndermeden önce yeniden sıralar.',
                    'Seçilen parçaları kimlikleri ve kaynak başlıklarıyla birlikte prompt’a koyun; modele yalnızca bu bağlamdan yanıt vermesini, [doc-3] gibi kaynak göstermesini ve yanıt yoksa "bilmiyorum" demesini söyleyin. Çok uzun bağlam maliyeti artırır ve modelin ortadaki bilgiyi kaçırmasına yol açabilir; bu yüzden yalnızca en ilgili parçaları gönderin. Meta veri ve erişim yetkisi filtrelerini sonradan değil erişim sırasında uygulayın; böylece kullanıcılar görmeye yetkili olmadıkları belgelerin içeriğini asla almaz.',
                    'Onlarca ila yüzlerce gerçek soru, kaynak belgeleri ve doğru yanıtlarından oluşan bir altın veri seti hazırlayın. Erişimi recall@k ve MRR ile ölçün: doğru parça hiç getirildi mi? Yanıtları faithfulness (her iddia kaynaklarca destekleniyor mu) ve answer relevance (soruyu gerçekten yanıtlıyor mu) ile ölçün. Net bir puanlama ölçütüne sahip LLM-as-a-judge değerlendirmeyi hızlandırır, ancak önce insan puanlarıyla kalibre edin. Prompt, model veya hat her değiştiğinde bu değerlendirmeleri CI’da çalıştırın ve üretimde gecikmeyi ve maliyeti izleyin.']],
            quiz: [
                'Akıl yürütme adımları ile araç çağrılarını dönüşümlü yürüten ajan deseni hangisidir?',
                ['Bir ajan iade yapmadan veya veri silmeden önce neden insan onayı istemelidir?', ['Token’lar daha ucuz olsun diye', 'Çünkü işlem geri alınması zordur ve prompt enjeksiyonuyla tetiklenebilir', 'Çünkü LLM’ler JSON okuyamaz', 'Model kendini otomatik olarak yeniden eğitsin diye']],
                ['RAG’de embedding modelinin görevi nedir?', ['Görselleri sıkıştırır', 'Metni vektörlere dönüştürerek anlamca benzer parçaların bulunmasını sağlar', 'Veritabanını şifreler', 'LLM’e parametre ekler']],
                'Bir yanıttaki her iddianın kaynak belgelerce desteklenip desteklenmediğini hangi metrik ölçer?'
            ]
        },
        it: {
            16: ['Agenti IA: Modelli che Agiscono', 'Capire come gli LLM pianificano i passi, chiamano strumenti e completano compiti entro limiti di sicurezza chiari.',
                ['Dal Chatbot all’Agente', 'Chiamata di Strumenti e Schemi di Funzione', 'Memoria, Pianificazione e Multi-Agente', 'Sicurezza e Valutazione degli Agenti'],
                ['Un chatbot risponde a un messaggio e si ferma. Un agente esegue un LLM in un ciclo: legge l’obiettivo, sceglie un passo, chiama uno strumento, legge il risultato e decide il passo successivo finché il compito non è concluso. Il pattern ReAct alterna ragionamento e azione. Esempio: un agente di assistenza controlla lo stato di un ordine, legge la politica di reso e poi prepara un rimborso. Usa un agente solo quando i passi non si possono fissare in anticipo; un flusso fisso costa meno ed è più facile da testare come normale workflow.',
                    'Ogni strumento è descritto con un nome, una spiegazione e un JSON Schema per gli argomenti, per esempio get_order(order_id: string). Il modello non esegue codice da solo: restituisce una chiamata strutturata, l’applicazione convalida gli argomenti e la esegue, e il risultato torna al modello. Il Model Context Protocol (MCP) standardizza il modo in cui le applicazioni offrono strumenti e dati ai modelli. Descrizioni chiare, argomenti convalidati e messaggi di errore utili spesso contano più della scelta del modello per il successo di un agente.',
                    'La memoria a breve termine è la cronologia della conversazione nella finestra di contesto; quella a lungo termine di solito sta in un database o in un vector store e viene recuperata quando serve. Nei compiti lunghi l’agente può scomporre l’obiettivo in un piano a passi e aggiornarlo dopo ogni risultato. Il pattern orchestratore-esecutori affida sottocompiti a più agenti in parallelo, per esempio per esaminare più fonti insieme. Ogni agente in più aggiunge costo in token, latenza e punti di guasto, quindi parti da un solo agente semplice.',
                    'Il testo di pagine web, email o documenti può contenere prompt injection che spinge l’agente a fare altro. Dai agli strumenti il minimo privilegio possibile, esegui il codice in una sandbox, limita il numero di passi e il budget, e chiedi l’approvazione di una persona prima di azioni difficili da annullare come trasferire denaro o cancellare dati. Conserva una traccia di ogni passo per l’audit. Valuta gli agenti su un insieme di compiti reali misurando tasso di successo, numero di passi, costo ed errori gravi; benchmark come SWE-bench e τ-bench seguono lo stesso approccio.']],
            17: ['RAG e Valutazione delle Applicazioni LLM', 'Ancorare le risposte di un LLM ai tuoi documenti, poi misurare in modo sistematico la qualità del recupero e delle risposte.',
                ['Perché il RAG', 'Chunking, Embedding e Ricerca Vettoriale', 'Costruire il Prompt e le Citazioni', 'Valutare le Applicazioni LLM'],
                ['Un LLM conosce solo i suoi dati di addestramento, ha una data limite di conoscenza e può avere allucinazioni con sicurezza. La Retrieval-Augmented Generation (RAG) cerca i passaggi rilevanti dei documenti quando arriva una domanda e li inserisce nel prompt, così il modello risponde basandosi su quelle fonti. La conoscenza si aggiorna senza riaddestrare e ogni risposta può citare le fonti. Il fine-tuning serve a cambiare stile o formato delle risposte; il RAG serve per conoscenze che cambiano spesso, come le policy aziendali.',
                    'I documenti vengono divisi in chunk di circa 200-800 token con una piccola sovrapposizione, perché le frasi non perdano significato. Un modello di embedding trasforma ogni chunk in un vettore, salvato in un database vettoriale come pgvector, Qdrant o FAISS. Anche la domanda diventa un vettore e il sistema recupera i top-k chunk con la similarità del coseno più alta. La ricerca ibrida combina vettori e BM25 per i termini esatti, come i codici prodotto, e un reranker riordina i candidati prima di passarli al modello.',
                    'Inserisci i chunk scelti nel prompt con il loro ID e il titolo della fonte, poi chiedi al modello di rispondere solo da quel contesto, di citare fonti come [doc-3] e di dire "non lo so" se la risposta manca. Un contesto troppo lungo costa di più e può far perdere al modello le informazioni nel mezzo, quindi invia solo i chunk più rilevanti. Applica i filtri su metadati e permessi durante il recupero, non dopo, così nessuno riceve contenuti di documenti che non è autorizzato a vedere.',
                    'Prepara un golden dataset con decine o centinaia di domande reali, i documenti di origine e le risposte corrette. Misura il recupero con recall@k e MRR: il chunk giusto è stato recuperato? Misura le risposte con faithfulness (ogni affermazione è supportata dalle fonti) e answer relevance (risponde davvero alla domanda). Un LLM-as-a-judge con una rubrica chiara velocizza la valutazione, ma va prima calibrato su giudizi umani. Esegui queste valutazioni in CI a ogni modifica di prompt, modello o pipeline, e monitora latenza e costi in produzione.']],
            quiz: [
                'Quale pattern di agente alterna passi di ragionamento e chiamate a strumenti?',
                ['Perché un agente dovrebbe chiedere l’approvazione di una persona prima di un rimborso o di cancellare dati?', ['Per rendere i token più economici', 'Perché l’azione è difficile da annullare e potrebbe essere innescata da una prompt injection', 'Perché gli LLM non sanno leggere JSON', 'Perché il modello si riaddestri da solo']],
                ['Nel RAG, a cosa serve il modello di embedding?', ['A comprimere immagini', 'A trasformare il testo in vettori per trovare passaggi con significato simile', 'A cifrare il database', 'Ad aggiungere parametri all’LLM']],
                'Quale metrica verifica che ogni affermazione di una risposta sia supportata dai documenti di origine?'
            ]
        },
        vi: {
            16: ['AI Agent: Mô hình Biết Hành động', 'Hiểu cách LLM lập kế hoạch từng bước, gọi công cụ và hoàn thành nhiệm vụ trong giới hạn an toàn rõ ràng.',
                ['Từ Chatbot đến Agent', 'Gọi Công cụ và Lược đồ Hàm', 'Bộ nhớ, Lập kế hoạch và Đa Agent', 'An toàn và Đánh giá Agent'],
                ['Chatbot trả lời một tin nhắn rồi dừng. Agent chạy LLM trong một vòng lặp: đọc mục tiêu, chọn một bước, gọi công cụ, đọc kết quả rồi quyết định bước tiếp theo cho đến khi xong việc. Mẫu ReAct xen kẽ suy luận và hành động. Ví dụ: agent hỗ trợ khách hàng kiểm tra trạng thái đơn hàng, đọc chính sách đổi trả rồi chuẩn bị hoàn tiền. Chỉ dùng agent khi không thể định sẵn các bước; luồng cố định làm thành workflow thông thường sẽ rẻ hơn và dễ kiểm thử hơn.',
                    'Mỗi công cụ được mô tả bằng tên, lời giải thích và JSON Schema cho tham số, ví dụ get_order(order_id: string). Mô hình không tự chạy mã; nó trả về một lời gọi có cấu trúc, ứng dụng kiểm tra tham số và thực thi, rồi gửi kết quả lại cho mô hình. Model Context Protocol (MCP) chuẩn hóa cách ứng dụng cung cấp công cụ và dữ liệu cho mô hình. Mô tả công cụ rõ ràng, tham số được kiểm tra và thông báo lỗi hữu ích thường quyết định thành công của agent nhiều hơn việc chọn mô hình.',
                    'Bộ nhớ ngắn hạn là lịch sử hội thoại trong cửa sổ ngữ cảnh; bộ nhớ dài hạn thường lưu trong cơ sở dữ liệu hoặc vector store và được truy xuất khi cần. Với nhiệm vụ dài, agent có thể chia mục tiêu thành kế hoạch từng bước và cập nhật sau mỗi kết quả. Mẫu điều phối-thực thi giao các nhiệm vụ con cho nhiều agent chạy song song, chẳng hạn nghiên cứu nhiều nguồn cùng lúc. Mỗi agent thêm vào làm tăng chi phí token, độ trễ và điểm lỗi, vì vậy hãy bắt đầu với một agent đơn giản.',
                    'Văn bản từ trang web, email hay tài liệu có thể chứa prompt injection khiến agent làm việc khác. Hãy cấp cho công cụ quyền tối thiểu, chạy mã trong sandbox, giới hạn số bước và ngân sách, và xin con người phê duyệt trước những hành động khó đảo ngược như chuyển tiền hay xóa dữ liệu. Lưu vết từng bước để kiểm toán. Đánh giá agent trên một tập nhiệm vụ thực tế và đo tỷ lệ thành công, số bước, chi phí và lỗi nghiêm trọng; các benchmark như SWE-bench và τ-bench cũng dùng cách tiếp cận này.']],
            17: ['RAG và Đánh giá Ứng dụng LLM', 'Neo câu trả lời của LLM vào tài liệu của bạn, rồi đo chất lượng truy xuất và câu trả lời một cách có hệ thống.',
                ['Vì sao cần RAG', 'Chia đoạn, Embedding và Tìm kiếm Vector', 'Xây dựng Prompt và Trích dẫn', 'Đánh giá Ứng dụng LLM'],
                ['LLM chỉ biết dữ liệu huấn luyện, có mốc giới hạn kiến thức và có thể bịa đặt một cách tự tin. Retrieval-Augmented Generation (RAG) tìm các đoạn tài liệu liên quan khi câu hỏi đến và chèn chúng vào prompt để mô hình trả lời dựa trên các nguồn đó. Kiến thức có thể cập nhật mà không cần huấn luyện lại, và mỗi câu trả lời có thể kèm trích dẫn. Fine-tuning phù hợp để đổi phong cách hoặc định dạng câu trả lời; RAG phù hợp với kiến thức thay đổi thường xuyên, như chính sách công ty.',
                    'Tài liệu được chia thành các chunk khoảng 200 đến 800 token, có chồng lấn nhỏ để câu không bị mất nghĩa. Mô hình embedding biến mỗi chunk thành vector, lưu trong cơ sở dữ liệu vector như pgvector, Qdrant hoặc FAISS. Câu hỏi cũng được biến thành vector, và hệ thống lấy ra top-k chunk có độ tương đồng cosine cao nhất. Tìm kiếm lai kết hợp vector với BM25 cho các thuật ngữ chính xác như mã sản phẩm, rồi reranker sắp xếp lại các ứng viên trước khi gửi cho mô hình.',
                    'Đưa các chunk đã chọn vào prompt cùng ID và tiêu đề nguồn, rồi yêu cầu mô hình chỉ trả lời từ ngữ cảnh đó, ghi nguồn như [doc-3] và nói "tôi không biết" nếu không có câu trả lời. Ngữ cảnh quá dài tốn kém hơn và dễ khiến mô hình bỏ sót thông tin ở giữa, nên chỉ gửi những chunk liên quan nhất. Áp dụng bộ lọc metadata và quyền truy cập ngay khi truy xuất chứ không phải sau đó, để người dùng không bao giờ nhận được nội dung tài liệu mà họ không được phép xem.',
                    'Xây dựng một golden dataset gồm vài chục đến vài trăm câu hỏi thật, kèm tài liệu nguồn và đáp án đúng. Đo truy xuất bằng recall@k và MRR: chunk đúng có được lấy ra không? Đo câu trả lời bằng faithfulness (mọi khẳng định đều có nguồn hỗ trợ) và answer relevance (thực sự trả lời câu hỏi). LLM-as-a-judge với tiêu chí rõ ràng giúp chấm nhanh hơn, nhưng hãy hiệu chỉnh nó bằng đánh giá của con người trước. Chạy các bài đánh giá này trong CI mỗi khi prompt, mô hình hoặc pipeline thay đổi, và theo dõi độ trễ cùng chi phí trong môi trường production.']],
            quiz: [
                'Mẫu agent nào xen kẽ các bước suy luận và lời gọi công cụ?',
                ['Vì sao agent nên xin con người phê duyệt trước khi hoàn tiền hoặc xóa dữ liệu?', ['Để token rẻ hơn', 'Vì hành động đó khó đảo ngược và có thể bị prompt injection kích hoạt', 'Vì LLM không đọc được JSON', 'Để mô hình tự huấn luyện lại']],
                ['Trong RAG, mô hình embedding làm gì?', ['Nén hình ảnh', 'Biến văn bản thành vector để tìm các đoạn có nghĩa tương tự', 'Mã hóa cơ sở dữ liệu', 'Thêm tham số cho LLM']],
                'Chỉ số nào kiểm tra xem mọi khẳng định trong câu trả lời có được tài liệu nguồn hỗ trợ hay không?'
            ]
        }
    };

    LESSONS.push(...lessons);
    QUIZ.push(...quiz);

    Object.entries(translations).forEach(([lang, entry]) => {
        lessons.forEach(({ id }) => {
            const [title, desc, sectionTitles, sectionBodies] = entry[id];
            (lessonTranslations[lang] = lessonTranslations[lang] || {})[id] = { title, desc };
            (sectionTranslations[lang] = sectionTranslations[lang] || {})[id] = sectionTitles;
            (sectionContentTranslations[lang] = sectionContentTranslations[lang] || {})[id] = sectionBodies;
        });
        if (typeof quizTranslations !== 'undefined' && quizTranslations[lang]) {
            quizTranslations[lang].push(...entry.quiz);
        }
    });
})();
